// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 firstBlock, uint256 secondBlock, address caller) public {
        uint256 amount = 10 ether;
        vm.assume(caller != address(0));
        vm.assume(firstBlock > 0 && secondBlock > 0);
        vm.assume(secondBlock >= firstBlock);
        vm.assume(secondBlock % 15 == 0);
        vm.deal(caller, amount * 2);

        vm.roll(firstBlock);
        vm.warp(firstBlock);
        vm.prank(caller);
        (bool ok1,) = address(c).call{value: amount}("");
        require(ok1, "first call failed unexpectedly");

        vm.roll(secondBlock);
        vm.warp(secondBlock);
        vm.prank(caller);
        (bool ok2,) = address(c).call{value: amount}("");

        if (firstBlock == secondBlock) {
            assertTrue(!ok2);
        } else {
            assertTrue(ok2);
        }
    }
}
